      }
      else if (key === '2-2') {
        /* v2.1 核力场 · 方案B（异能设定收敛）：
         *   结合能释放：E = 质量 × 8×10⁴ kJ/g（可控微裂变，截面转化率 0.1% —— 规避"1g 铀≈2kg 汽油"的物理破绽）
         *   衰变加速：  E = 质量 × 400 kJ/g（跨越衰变势垒的活化能，效果=放射性污染缓发） */
        const gm = 0.1 * Math.pow(10000, c.nmass / 100); // 0.1g ~ 1000g
