      list.push('<div class="preview-item"><span><b>' + esc(c.名称) + '</b>　' + famName + '·' + esc(br) + '　<span style="color:#64748b;">' + esc(c.fx) + '</span></span><span class="pi-tag ' + tag + '">' + (tag.indexOf('主') >= 0 ? '主亲和' : '次亲和') + '</span></div>');
    });
    $('#circuitPreview').innerHTML = list.length ? list.join('') : '<div class="preview-item"><span style="color:#64748b;">（未选择亲和，无初始回路）</span></div>';
  }

  function 四维档位() {
    return ATTRIB_GRADES[attrSel.energy].档 + '/' + ATTRIB_GRADES[attrSel.mind].档 + '/' + ATTRIB_GRADES[attrSel.sustain].档 + '/' + ATTRIB_GRADES[attrSel.burst].档;
  }
  function renderSummary() {
    var spend = 总花费(), budget = 点预算(), left = budget - spend;
    var name = $('#inputName').value.trim();
    var custom = presetMode === 'custom';
    var ok = name.length > 0 && mains.length >= 1 && (!custom || (left >= 0 && subs.length <= capS && mains.length <= capM));
    $('#btnFinishSetup').disabled = !ok;
    var s;
    if (!custom) {
      s = '• 预设模板「' + presetMode + '」已套用：' + gender + ' | 四维 ' + 四维档位() + ' | 亲和 主' + mains.length + '次' + subs.length + ' | 总花费 <b class="points-ok">' + spend + '</b> 点（官方模板 · 不校验点数）';
    } else {
      s = '• 当前选档：' + gender + ' [' + difficulty + ' ' + budget + '点] | 四维 ' + 四维档位() + ' | 亲和 主' + mains.length + '次' + subs.length + ' | 已用 <b class="' + (left >= 0 ? 'points-ok' : 'points-over') + '">' + spend + '</b> 点 · 剩余 <b class="' + (left >= 0 ? 'points-ok' : 'points-over') + '">' + left + '</b> 点';
    }
    if (!name) s += '<br>• 尚未填写施法者姓名。';
    else if (mains.length < 1) s += '<br>• 必须至少选定 1 个主亲和。';
    else if (custom && left < 0) s += '<br>• 点数超支 ' + (-left) + ' 点！请降低档位或减少亲和。';
    else s += '<br>• 将为全部主/次亲和分支自动授予基础固定回路（合计 ' + (mains.length + subs.length) + ' 条）。';
    $('#summaryNotice').innerHTML = s;
  }

  function renderAll() {
    var locked = presetMode !== 'custom';
    ['#affinityTreeContainer', '#attrRows', '#difficultyRow'].forEach(function (sel) {
      var el = $(sel); if (el) el.classList.toggle('locked', locked);
    });
    renderAffinity(); renderAttrs(); renderPreview(); renderSummary();
  }

  /* ═══════════════════ 事件 ═══════════════════ */
  document.body.addEventListener('click', function (ev) {
    var t = ev.target;
    if (t.dataset && t.dataset.gender) {
      gender = t.dataset.gender;
      document.querySelectorAll('.gender-pill').forEach(function (p) { p.classList.toggle('active', p.dataset.gender === gender); });
      renderSummary();
      return;
    }
    if (t.dataset && t.dataset.preset) {
      if (t.dataset.preset === 'custom') {
        presetMode = 'custom';
        $('#diffRuleTag').textContent = DIFFICULTY[difficulty].rule;   // 解锁提示移除
        document.querySelectorAll('.preset-pill').forEach(function (p) { p.classList.toggle('active', p.dataset.preset === 'custom'); });
        renderAll();
      } else {
        applyPreset(t.dataset.preset);
      }
      return;
    }
    if (t.dataset && t.dataset.diff) {
      if (presetMode !== 'custom') return;   // 预设锁定：难度不可改
      setDifficulty(t.dataset.diff, false);
      if (mains.length > capM) mains = mains.slice(0, capM);
      if (subs.length > capS) subs = subs.slice(0, capS);
      renderAll();
      return;
    }
    var gp = t.closest('.grade-pill');
    if (gp && gp.dataset.attr) {
      if (presetMode !== 'custom') return;   // 预设锁定：四维不可改
      attrSel[gp.dataset.attr] = parseInt(gp.dataset.g, 10);
      renderAll();
      return;
    }
  });
  $('#inputName').addEventListener('input', renderSummary);

  /* ═══════════════════ 时间/开场白（沿用扩展，可改） ═══════════════════ */
  var DEFAULT_TIME = '2026年9月1日，08：00';
  var DEFAULT_OPENING = '2026年，魔素渗入这个世界的每个角落已经二十七年。路灯里淌着微光，换电站取代了旧时代的加油站，义务教育里的魔法课和体育课地位相当。今天是你开启身份档案的第一天……';
  function parseTime(label) {
    var s = String(label || '').replace(/[，,]/g, ',').replace(/[：:]/g, ':').replace(/\s+/g, '').trim();
    var m = s.match(/^(\d{1,4})年(\d{1,2})月(\d{1,2})日,(\d{1,2}):(\d{2})$/);
    if (!m) return null;
    var t = Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5]);
    return Number.isNaN(t) ? null : Math.round(t / 60000);
  }

  /* ═══════════════════ 确认开局（点数制 → 存档 → 落盘） ═══════════════════ */
  function toast(ok, text) { var m = $('#msg'); m.style.color = ok ? '#c6ff00' : '#f43f5e'; m.textContent = text; }

  function circuitFor(gr, br, idx) {
    var p = BRANCH_CIRCUIT[br];
    if (!p || !E) return null;
    var params = Object.assign(E.initParams(p.famKey), p.params);
    var q = E.quote({ fam: p.famKey, e: p.e, c: params }, ctxRef());
    var budget = E.budgetFrom ? E.budgetFrom(p.famKey, params, q.E_out) : null;
    return {
      id: 'fx-' + (idx < 9 ? '0' + (idx + 1) : idx + 1),
      名称: p.名称, type: 'fixed', 族: gr.family, famKey: p.famKey,
      分支: E.branchOf(p.famKey, params),
      实体: p.famKey === 'flow' ? String(E.curKey(params)) : null,
      参数向量: params, 注册e: p.e,
      参数明细: E.readableParams(p.famKey, params),
      微调预算: budget, 微调预算明细: E.readableBudget ? E.readableBudget(budget) : null,
      基线账单: { 输出kJ: q.E_out, 计费kJ: q.bill, 精神: q.mind, 一句话效果: p.fx },
      uses: null, 来源: '开局预设', 审核存档: null, 审核状态: '免审'
    };
  }

  var ctxRef = function () {
    var mainsB = mains.map(function (b) { var f = ''; AFFINITY_SCHEMA.forEach(function (g) { if (g.branches.indexOf(b) >= 0) f = g.family; }); return { 族: f, 分支: b }; });
    var subsB = subs.map(function (b) { var f = ''; AFFINITY_SCHEMA.forEach(function (g) { if (g.branches.indexOf(b) >= 0) f = g.family; }); return { 族: f, 分支: b }; });
    var E0 = ATTRIB_GRADES[attrSel.energy], M0 = ATTRIB_GRADES[attrSel.mind], S0 = ATTRIB_GRADES[attrSel.sustain], B0 = ATTRIB_GRADES[attrSel.burst];
    var eKJ = Math.round(E0.能量MJ * 1000), sp = M0.精神;
    return {
      aff: { main: mainsB, subs: subsB },
      scene: { wind: 40, mat: 3000, water: false },
      char: { burstKW: B0.瞬时kW, sustainKW: S0.持续W / 1000, speed: 1, eCur: eKJ, mCur: sp, mMax: sp, body: '正常' },
      tuned: []
    };
  };

  $('#btnFinishSetup').addEventListener('click', function () {
    var name = $('#inputName').value.trim();
    if (!gender || !name) { toast(false, '请填写姓名并选择性别'); return; }
    if (mains.length < 1) { toast(false, '至少选定 1 个主亲和'); return; }
    if (presetMode === 'custom' && 总花费() > 点预算()) { toast(false, '点数超支 ' + (总花费() - 点预算()) + ' 点'); return; }
    if (typeof getVariables !== 'function') { toast(false, '需要酒馆助手环境'); return; }
    var timeLabel = DEFAULT_TIME;
    if (!parseTime(timeLabel)) { toast(false, '剧情时间格式错误'); return; }

    var mainsB = mains.map(function (b) { var f = ''; AFFINITY_SCHEMA.forEach(function (g) { if (g.branches.indexOf(b) >= 0) f = g.family; }); return { 族: f, 分支: b }; });
    var subsB = subs.map(function (b) { var f = ''; AFFINITY_SCHEMA.forEach(function (g) { if (g.branches.indexOf(b) >= 0) f = g.family; }); return { 族: f, 分支: b }; });
    var E0 = ATTRIB_GRADES[attrSel.energy], M0 = ATTRIB_GRADES[attrSel.mind], S0 = ATTRIB_GRADES[attrSel.sustain], B0 = ATTRIB_GRADES[attrSel.burst];
    var eKJ = Math.round(E0.能量MJ * 1000), sp = M0.精神;

    var g = {
      version: 2,
      主角: {
        能量kJ: { 当前: eKJ, 上限: eKJ }, 精神点: { 当前: sp, 上限: sp },
        爆发线kW: B0.瞬时kW, 持续线kW: S0.持续W / 1000,
        战斗中: false, 身体状态: '正常',
        剧情时间: { label: timeLabel }, 上次结算min: parseTime(timeLabel)
      },
      补给物品: [], 回路库: [],
      槽位: { 固定槽: [null, null, null, null, null, null, null, null, null, null], 自由槽: [null, null, null] },
      亲和: { 主分支: mainsB, 次分支: subsB },
      待扣单: [],
      场景: { 风力档: 40, 可塑无机物kJ: 3000, 水体在场: false },
      感情追踪: { '陆安': { 自洽: 10, 共情: 6, 解构: 10, '对主角的信任度': 5, 长期目标: '', 短期目标: '', 怎么看待主角: '' } }
    };
    var slot = 0;
    mains.concat(subs).forEach(function (br) {
      var gr = null;
      AFFINITY_SCHEMA.forEach(function (x) { if (x.branches.indexOf(br) >= 0) gr = x; });
      if (!gr) return;
      var c = circuitFor(gr, br, slot);
      if (!c) return;
      g.回路库.push(c);
      if (slot < 10) g.槽位.固定槽[slot] = c.id;
      slot++;
    });
    // 新手包补给（固定发放 4 种库存：晶体/导液=库存型整条入；创伤=一补给一牌）
    预设补给.forEach(function (ps) {
      if (ps.名称 === '魔素晶体' || ps.名称 === '魔素导液') {
        g.补给物品.push(JSON.parse(JSON.stringify(ps)));
      } else {
        for (var k = 0; k < ps.数量; k++) {
          var one = JSON.parse(JSON.stringify(ps));
          one.数量 = 1;
          one.uid = ps.名称 + '#开局' + k;
          g.补给物品.push(one);
        }
      }
    });

    $('#btnFinishSetup').disabled = true; toast(true, '正在写入…');
    Promise.resolve(updateVariablesWith(function (v) { v['渐变带'] = g; return v; }, { type: 'chat' })).then(function () {
      return Promise.resolve(setChatMessages([{ message_id: 0, message: DEFAULT_OPENING }], { refresh: 'all' })).catch(function () {});
    }).then(function () {
      var snap = JSON.parse(JSON.stringify(g)); if (snap['主角']) delete snap['主角']['上次结算min'];
      return Promise.resolve(updateVariablesWith(function (v) { v.stat_data = v.stat_data || {}; v.stat_data['渐变带'] = snap; return v; }, { type: 'message', message_id: 0 })).catch(function () {});
    }).then(function () {
      toast(true, '✓ 开局完成！神经回路已烧录' + slot + ' 条，开场白写入第 0 楼。');
    }).catch(function (e) {
      toast(false, '失败：' + e);
      $('#btnFinishSetup').disabled = false;
    });
  });

  /* ═══════════════════ 启动 ═══════════════════ */
  renderAll();
  setDifficulty('普通', false);
  if (typeof getVariables !== 'function') toast(false, '需要酒馆助手环境（请在酒馆消息楼层内打开本页）');
})();
</script>
